import { AuthOptions } from "../route/auth-options.js";
import { MediaRoute } from "../route/media.js";
import { HttpOptions, ProviderID, ToolDefinition, mergeHttpOptions, } from "../schema/index.js";
import * as OpenAIChat from "../protocols/openai-chat.js";
import * as OpenAIResponses from "../protocols/openai-responses.js";
import { withOpenAIOptions } from "./openai-options.js";
import { OpenAIImages } from "../protocols/openai-images.js";
import { OpenAISpeech } from "../protocols/openai-speech.js";
import { OpenAITranscription } from "../protocols/openai-transcription.js";
export const id = ProviderID.make("openai");
export const routes = [OpenAIResponses.route, OpenAIChat.route];
export const imageGeneration = (options = {}) => ToolDefinition.make({
    name: "image_generation",
    description: "Generate or edit an image using OpenAI's hosted image generation tool.",
    inputSchema: { type: "object", properties: {}, additionalProperties: false },
    native: {
        openai: {
            type: "image_generation",
            action: options.action,
            background: options.background,
            input_fidelity: options.inputFidelity,
            output_compression: options.outputCompression,
            output_format: options.outputFormat,
            partial_images: options.partialImages,
            quality: options.quality,
            size: options.size,
        },
    },
});
const auth = (options) => AuthOptions.bearer(options, "OPENAI_API_KEY");
const defaults = (input) => {
    const { apiKey: _, auth: _auth, baseURL: _baseURL, queryParams: _queryParams, ...rest } = input;
    return rest;
};
const configuredRoute = (route, input) => route.with({
    auth: auth(input),
    endpoint: { baseURL: input.baseURL, query: input.queryParams },
});
export const configure = (input = {}) => {
    const responsesRoute = configuredRoute(OpenAIResponses.route, input);
    const chatRoute = configuredRoute(OpenAIChat.route, input);
    const modelDefaults = defaults(input);
    const responses = (id) => responsesRoute
        .with(withOpenAIOptions(id, modelDefaults))
        .model({ id });
    const chat = (id) => chatRoute.with(withOpenAIOptions(id, modelDefaults)).model({
        id,
        compatibility: { supportsPromptCacheKey: true },
    });
    const deployment = MediaRoute.deployment(input, auth(input));
    const media = {
        ...deployment,
        http: mergeHttpOptions(deployment.http, input.queryParams === undefined ? undefined : new HttpOptions({ query: input.queryParams })),
    };
    const image = (modelID) => OpenAIImages.model({ ...media, id: modelID });
    const speech = (modelID) => OpenAISpeech.model({ ...media, id: modelID });
    const transcription = (modelID) => OpenAITranscription.model({ ...media, id: modelID });
    return {
        id,
        model: responses,
        responses,
        chat,
        image,
        speech,
        transcription,
        configure,
    };
};
export const provider = configure();
const config = ({ apiKey, baseURL, body, headers: given, organization, project, queryParams, ...providerOptions }) => {
    const headers = {
        ...(organization === undefined ? {} : { "OpenAI-Organization": organization }),
        ...(project === undefined ? {} : { "OpenAI-Project": project }),
        ...given,
    };
    return {
        apiKey,
        baseURL,
        headers: Object.keys(headers).length === 0 ? undefined : headers,
        http: body === undefined ? undefined : { body },
        providerOptions,
        queryParams,
    };
};
export const model = (modelID, settings) => {
    return configure(config(settings)).responses(modelID);
};
export const chatModel = (modelID, settings) => configure(config(settings)).chat(modelID);
export const responses = provider.responses;
export const chat = provider.chat;
export const image = provider.image;
export const speech = provider.speech;
export const transcription = provider.transcription;
